 "content": "from collections import Counter


def _center_lanes(values, background):
    """Return the middle lane(s) of each contiguous non-background edge run."""
    lanes = []
    i = 0
    while i < len(values):
        if values[i] == background:
            i += 1
            continue
        j = i
        while j < len(values) and values[j] != background:
            j += 1
        length = j - i
        if length % 2:
            lanes.append(i + length // 2)
        else:
            lanes.extend((i + length // 2 - 1, i + length // 2))
        i = j
    return lanes


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    markers = [(r, c, grid[r][c])
               for r in range(1, h - 1)
               for c in range(1, w - 1)
               if grid[r][c] != background]
    if not markers:
        return out
    ray_color = markers[0][2]

    # Center lane(s) of each colored edge segment send an inward straight ray.
    # The first non-background interior cell stops the ray and becomes 4.
    for c in _center_lanes(grid[0], background):
        r = 1
        while r < h - 1 and grid[r][c] == background:
            out[r][c] = ray_color
            r += 1
        if r < h - 1 and grid[r][c] != background:
            out[r][c] = 4

    for c in _center_lanes(grid[h - 1], background):
        r = h - 2
        while r > 0 and grid[r][c] == background:
            out[r][c] = ray_color
            r -= 1
        if r > 0 and grid[r][c] != background:
            out[r][c] = 4

    for r in _center_lanes([grid[y][0] for y in range(h)], background):
        c = 1
        while c < w - 1 and grid[r][c] == background:
            out[r][c] = ray_color
            c += 1
        if c < w - 1 and grid[r][c] != background:
            out[r][c] = 4

    for r in _center_lanes([grid[y][w - 1] for y in range(h)], background):
        c = w - 2
        while c > 0 and grid[r][c] == background:
            out[r][c] = ray_color
            c -= 1
        if c > 0 and grid[r][c] != background:
            out[r][c] = 4
    return out
